function validateEconomy(economy: CampaignEconomy) {
  if (!economy || !Array.isArray(economy.rpTransactions) || !Array.isArray(economy.requisitions) || !Array.isArray(economy.claimedAssets) || !Array.isArray(economy.discoveryTemplates) || !Array.isArray(economy.discoveries)) throw new Error('Campaign economy has an invalid collection shape.');
  for (const entry of economy.rpTransactions) {
    if (!entry.id || !Number.isInteger(entry.amount) || entry.amount === 0 || !entry.reason?.trim() || !entry.idempotencyKey?.trim()) throw new Error('Campaign RP ledger contains an invalid transaction.');
  }
  for (const requisition of economy.requisitions) {
    if (!requisition.id || !requisition.source?.trim() || !requisition.target?.trim() || !requisition.effect?.trim() || !Number.isInteger(requisition.cost) || requisition.cost < 0) throw new Error('Campaign economy contains an invalid requisition.');
  }
  for (const asset of economy.claimedAssets) {
    if (!asset.id || !asset.title?.trim() || !asset.assetClass || !asset.status || !asset.publicDescription?.trim()) throw new Error('Campaign economy contains an invalid claimed asset.');
  }
  const templateIds = new Set<string>();
  for (const template of economy.discoveryTemplates) {
    if (!template.id || templateIds.has(template.id) || !template.title?.trim() || !template.sourcePath?.trim()) throw new Error('Campaign economy contains an invalid discovery template.');
    templateIds.add(template.id);
  }
  for (const discovery of economy.discoveries) {
    if (!discovery.id || !templateIds.has(discovery.templateId) || !discovery.templateTitle?.trim()) throw new Error('Campaign economy contains an invalid discovery instance.');
  }
}

