    if (idempotencyKey && this.memory.control.economy.rpTransactions.some((entry) => entry.idempotencyKey === idempotencyKey)) return this.memory.control.economy.rpTransactions.find((entry) => entry.idempotencyKey === idempotencyKey)!;
