  createRequisition(input: Pick<CampaignRequisition, 'title' | 'kind' | 'cost' | 'source' | 'target' | 'effect'>, actor: ActorContext) { assertGm(actor); const fixed: Partial<Record<CampaignRequisition['kind'], number>> = { 'rank-advancement': 1, 'major-reinforcement': 3 }; if (!Number.isInteger(input.cost) || input.cost < 1) throw new Error('Requisition cost must be a positive whole RP amount.'); if (fixed[input.kind] !== undefined && fixed[input.kind] !== input.cost) throw new Error(`${input.kind} has a fixed canonical cost of ${fixed[input.kind]} RP.`); const entry: CampaignRequisition = { id: randomUUID(), title: this.requireText(input.title, 'Requisition title'), kind: input.kind, cost: input.cost, source: this.requireText(input.source, 'Plausible source'), target: this.requireText(input.target, 'Legal target'), effect: this.requireText(input.effect, 'Exact effect'), status: 'proposed', createdAt: now(), updatedAt: now(), audit: [{ at: now(), action: 'proposed' }] }; this.memory.control.economy.requisitions.push(entry); this.controlRecord('requisition', entry.id, 'proposed', actor, entry); return clone(entry); }
  advanceRequisition(id: string, status: 'approved' | 'spent' | 'void', actor: ActorContext, reason?: string) { assertGm(actor); const entry = this.memory.control.economy.requisitions.find((row) => row.id === id); if (!entry) throw new Error('The requisition is unavailable.'); if (status === 'approved' && entry.status !== 'proposed') throw new Error('Only proposed requisitions may be approved.'); if (status === 'spent' && entry.status !== 'approved') throw new Error('Only approved requisitions may spend RP.'); if (status === 'void' && !reason?.trim()) throw new Error('A reason is required to void a requisition.'); if (status === 'spent') this.recordRp(-entry.cost, 'requisition-debit', `Requisition: ${entry.title}.`, actor, 'requisition', entry.id, `requisition:${entry.id}`); entry.status = status; entry.updatedAt = now(); if (status === 'approved') entry.approvedAt = now(); if (status === 'spent') entry.spentAt = now(); if (status === 'void') entry.voidReason = reason!.trim(); entry.audit.push({ at: now(), action: status, reason: reason?.trim() }); this.controlRecord('requisition', id, status, actor, { reason }); return clone(entry); }
  createClaimedAsset(input: Omit<ClaimedAsset, 'id' | 'createdAt' | 'updatedAt' | 'audit' | 'status'>, actor: ActorContext) { assertGm(actor); const asset: ClaimedAsset = { id: randomUUID(), ...input, title: this.requireText(input.title, 'Asset title'), targetSource: this.requireText(input.targetSource, 'Asset target/source'), claimant: this.requireText(input.claimant, 'Claimant'), provenance: this.requireText(input.provenance, 'Provenance'), recovery: this.requireText(input.recovery, 'Recovery condition'), extraction: this.requireText(input.extraction, 'Extraction condition'), tacticalRisk: this.requireText(input.tacticalRisk, 'Tactical risk'), currentCustodian: this.requireText(input.currentCustodian, 'Current custodian'), condition: this.requireText(input.condition, 'Condition'), publicDescription: this.requireText(input.publicDescription, 'Player-safe description'), status: 'recovered', createdAt: now(), updatedAt: now(), audit: [{ at: now(), action: 'recovered', reason: 'Recorded by GM.' }] }; this.memory.control.economy.claimedAssets.push(asset); this.controlRecord('claimed-asset', asset.id, 'recovered', actor, asset); return clone(asset); }
