  issueDiscovery(input: { templateId: string; ownerMode: DiscoveryInstance['ownerMode']; ownerIdentityId?: string; publicDescription?: string; linkedEvidenceIds?: string[]; linkedAssetIds?: string[]; namedDebt?: string; nextComplication?: string }, actor: ActorContext) { assertGm(actor); const template = this.memory.control.economy.discoveryTemplates.find((row) => row.id === input.templateId); if (!template) throw new Error('The discovery template is unavailable.'); if (input.ownerMode === 'personal' && !this.memory.identities.some((row) => row.id === input.ownerIdentityId && row.role === 'player')) throw new Error('A personal discovery requires a configured player owner.'); const instance: DiscoveryInstance = { id: randomUUID(), templateId: template.id, templateTitle: template.title, ownerMode: input.ownerMode, ownerIdentityId: input.ownerMode === 'personal' ? input.ownerIdentityId : undefined, status: 'unused', progression: template.stages, linkedEvidenceIds: input.linkedEvidenceIds ?? [], linkedAssetIds: input.linkedAssetIds ?? [], namedDebt: input.namedDebt?.trim(), nextComplication: input.nextComplication?.trim(), publicDescription: input.publicDescription?.trim() || template.playerText, createdAt: now(), updatedAt: now(), audit: [{ at: now(), action: 'issued', reason: 'GM issued canonical discovery template.' }] }; this.memory.control.economy.discoveries.push(instance); this.controlRecord('discovery', instance.id, 'issued', actor, instance); return clone(instance); }
