  createOperation(input: Pick<CampaignOperation, 'title' | 'system' | 'narrativePurpose' | 'statedStakes' | 'playerBriefing' | 'sourceReference' | 'participants' | 'objectives' | 'timePlan'>, actor: ActorContext) { assertGm(actor); if (!['kill-team', 'warhammer-40000', 'imperium-maledictum'].includes(input.system)) throw new Error('Choose Kill Team, Warhammer 40,000, or Imperium Maledictum.'); if (!Array.isArray(input.participants) || !input.participants.length || input.participants.some((id) => !this.memory.identities.some((identity) => identity.id === id && identity.role === 'player'))) throw new Error('Choose one or more configured player participants.'); if (!Array.isArray(input.objectives) || !input.objectives.length || input.objectives.some((entry) => !entry.title?.trim() || !entry.publicSummary?.trim())) throw new Error('Record at least one complete declared operation objective.'); const entry: CampaignOperation = { id: randomUUID(), title: this.operationText(input.title, 'Operation title'), system: input.system, status: 'draft', narrativePurpose: this.operationText(input.narrativePurpose, 'Narrative purpose'), statedStakes: this.operationText(input.statedStakes, 'Stated stakes'), playerBriefing: this.operationText(input.playerBriefing, 'Player-safe briefing'), sourceReference: this.operationText(input.sourceReference, 'Canonical source reference'), participants: [...new Set(input.participants)], objectives: input.objectives.map((objective) => ({ ...objective, id: objective.id || randomUUID(), status: objective.status ?? 'open' })), missionTruth: { enemyFacts: '', terrain: '', hiddenObjectives: '', escalation: '', extractionRules: '', privateConsequences: '', corrections: [] }, timePlan: this.operationTimePlan(input.timePlan), deploymentIds: [], createdAt: now(), updatedAt: now(), audit: [{ at: now(), action: 'created' }] }; this.memory.control.operations.push(entry); this.controlRecord('operation', entry.id, 'created', actor, entry); return clone(entry); }
