  updateOperation(id: string, input: Partial<Pick<CampaignOperation, 'title' | 'narrativePurpose' | 'statedStakes' | 'playerBriefing' | 'sourceReference' | 'participants' | 'objectives' | 'timePlan' | 'deploymentPolicy'>>, actor: ActorContext) { assertGm(actor); const entry = this.operation(id); if (!['draft', 'prepared'].includes(entry.status)) throw new Error('Only draft or prepared operations may be edited normally.'); if (input.title !== undefined) entry.title = this.operationText(input.title, 'Operation title'); if (input.narrativePurpose !== undefined) entry.narrativePurpose = this.operationText(input.narrativePurpose, 'Narrative purpose'); if (input.statedStakes !== undefined) entry.statedStakes = this.operationText(input.statedStakes, 'Stated stakes'); if (input.playerBriefing !== undefined) entry.playerBriefing = this.operationText(input.playerBriefing, 'Player-safe briefing'); if (input.sourceReference !== undefined) entry.sourceReference = this.operationText(input.sourceReference, 'Canonical source reference'); if (input.timePlan) entry.timePlan = this.operationTimePlan(input.timePlan); if (input.deploymentPolicy) entry.deploymentPolicy = this.deploymentPolicy(input.deploymentPolicy); if (input.objectives) entry.objectives = input.objectives.map((objective) => ({ ...objective, id: objective.id || randomUUID() })); entry.updatedAt = now(); entry.audit.push({ at: now(), action: 'updated' }); this.controlRecord('operation', id, 'updated', actor, input); return clone(entry); }
