  removeUnitAttachment(id: string, actor: ActorContext) { validateRole(actor.role); const index = this.memory.control.unitAttachments.findIndex(row => row.id === id); if (index < 0) throw new Error('The attachment is unavailable.'); const row = this.memory.control.unitAttachments[index]; const roster = row.rosterId ? this.memory.control.rosterDrafts.find(entry => entry.id === row.rosterId) : undefined; if (row.scope === 'permanent') assertGm(actor); else if (!roster || roster.status !== 'draft' || (actor.role === 'player' && roster.ownerIdentityId !== actor.identityId) || (actor.role !== 'player' && !gmRoles.includes(actor.role))) throw new Error('Roster attachments may only be removed from your own draft roster.'); this.memory.control.unitAttachments.splice(index, 1); if (roster) { const child = this.memory.control.collectionUnits.find(entry => entry.id === row.childUnitId); roster.unitIds = roster.unitIds.filter(unitId => unitId !== row.childUnitId); roster.attachmentIds = roster.attachmentIds?.filter(attachmentId => attachmentId !== row.id); roster.totalPoints -= child?.approximatePoints ?? 0; roster.updatedAt = now(); } this.controlRecord('unit-attachment', id, 'removed', actor, row); return clone(row); }
